(function(){
'use strict';
const $=id=>document.getElementById(id),api=()=>window.CAGE_BACKEND;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const empty=msg=>`<div class="academy-empty">${esc(msg)}</div>`;
const btn=(action,label,id='',primary=false)=>`<button type="button" class="${primary?'primary':'secondary'}-button" data-academy="${action}" data-id="${esc(id)}">${esc(label)}</button>`;
const tag=(text,tone='')=>`<span class="academy-tag ${tone}">${esc(text)}</span>`;
const table=(heads,rows)=>rows.length?`<div class="academy-table"><table><thead><tr>${heads.map(h=>`<th scope="col">${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:empty('No matching records yet.');
const money=(n,c='MWK')=>`${esc(c)} ${Number(n||0).toLocaleString(undefined,{maximumFractionDigits:2})}`;
const day=()=>new Date().toLocaleDateString('en-CA',{timeZone:'Africa/Blantyre'});
const time=v=>v?new Date(v).toLocaleString('en-GB',{timeZone:'Africa/Blantyre',dateStyle:'medium',timeStyle:'short'}):'—';
const localTime=v=>v?new Date(new Date(v).getTime()+120*60000).toISOString().slice(0,16):'';
const key=()=>`cage-academy:${api()?.currentProfile()?.id}`;
let data=null,tab='overview',query='',selected='',loading=null,loadError='';
const tabs=[['overview','Overview'],['courses','Courses'],['cohorts','Cohorts'],['learners','Learners'],['timetable','Timetable'],['fees','Fees & sponsors'],['reports','Reports'],['stem','STEM applications']];
const panel=document.querySelector('[data-view-panel="training"]');
const root=document.createElement('div');root.className='academy';root.id='academy';panel.append(root);
const course=id=>data?.courses.find(r=>r.id===id),cohort=id=>data?.cohorts.find(r=>r.id===id),learner=id=>data?.learners.find(r=>r.id===id);
const staff=id=>data?.staff.find(r=>r.id===id)?.full_name||'Unassigned';
const courseFor=l=>course(cohort(l.cohort_id)?.course_id);
const canEdit=()=>api()?.moduleLevel('training')==='edit';
const canApprove=()=>canEdit()&&['admin','manager'].includes(api()?.currentProfile()?.role);
const action=(a,label,id='',primary=false)=>canEdit()?btn(a,label,id,primary):'';
const students=()=>data.learners.filter(l=>(!selected||l.cohort_id===selected)&&`${l.full_name} ${l.email||''} ${cohort(l.cohort_id)?.name||''} ${l.sponsor||''}`.toLowerCase().includes(query.toLowerCase()));
function progress(l){
 const c=courseFor(l)||{},sessions=data.sessions.filter(s=>s.cohort_id===l.cohort_id&&!s.cancelled&&new Date(s.ends_at)<=new Date());
 const counted=sessions.filter(s=>!data.attendance.some(a=>a.session_id===s.id&&a.learner_id===l.id&&a.status==='Excused'));
 const present=counted.filter(s=>data.attendance.some(a=>a.session_id===s.id&&a.learner_id===l.id&&['Present','Late'].includes(a.status))).length;
 const attendance=counted.length?Math.round(present*10000/counted.length)/100:0;
 const mins=data.practical.filter(p=>p.learner_id===l.id&&p.signed_off_by).reduce((s,p)=>s+Number(p.minutes),0);
 const latest=req=>data.assessments.filter(a=>a.learner_id===l.id&&a.assessment_type.trim().toLowerCase()===req.trim().toLowerCase()).sort((a,b)=>b.assessed_at.localeCompare(a.assessed_at)||b.id.localeCompare(a.id))[0];
 const missing=(c.required_assessments||[]).filter(req=>!['Pass','Competent'].includes(latest(req)?.result));
 const minor=l.date_of_birth?new Date(l.date_of_birth)>new Date(new Date().setFullYear(new Date().getFullYear()-18)):c.category==='STEM';
 const reasons=[];if(!l.documents_complete)reasons.push('Check required documents');if(minor&&(!l.guardian_consent||!l.guardian_name?.trim()||!l.guardian_phone?.trim()))reasons.push('Record guardian contact and consent');
 if(Number(c.minimum_attendance)>0&&(!counted.length||attendance<Number(c.minimum_attendance)))reasons.push(`Attendance ${attendance}% / ${c.minimum_attendance}% required`);
 if(mins<Number(c.practical_minutes))reasons.push(`Practical ${mins} / ${c.practical_minutes} signed minutes`);
 missing.forEach(r=>reasons.push(`Pass ${r}`));if(data.sessions.some(s=>s.cohort_id===l.cohort_id&&!s.cancelled&&new Date(s.ends_at)>new Date()))reasons.push('Finish scheduled sessions');if(l.stage==='Withdrawn')reasons.push('Learner has withdrawn');
 return {attendance,mins,reasons,ready:reasons.length===0,sessions:counted.length};
}
function remember(){try{sessionStorage.setItem(key(),JSON.stringify({tab,query,selected}));}catch{}}
async function load(){
 if(!api()?.currentProfile())return;if(loading)return loading;
 loading=(async()=>{try{data=await api().academyData();loadError='';render();}catch(e){loadError=e.message;render();}finally{loading=null;}})();return loading;
}
function render(){
 root.innerHTML=`<div class="academy-toolbar"><nav class="academy-tabs" role="tablist" aria-label="Training Academy">${tabs.map(([k,v])=>`<button role="tab" aria-selected="${tab===k}" data-academy="tab" data-id="${k}">${v}</button>`).join('')}</nav><div class="academy-filter"><input id="academy-query" type="search" aria-label="Search Academy" placeholder="Search learners, courses or cohorts" value="${esc(query)}"><select id="academy-cohort-filter" aria-label="Filter cohort"><option value="">All cohorts</option>${(data?.cohorts||[]).map(c=>`<option value="${c.id}" ${selected===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select>${btn('refresh','Refresh')}</div></div><div id="academy-content" role="tabpanel"></div>`;
 const content=$('academy-content');if(tab==='stem'){window.CAGE_STEM?.render(content);return;}if(loadError){content.innerHTML=`<p class="academy-error" role="alert">${esc(loadError)}</p>${btn('refresh','Retry')}`;return;}if(!data){content.innerHTML=empty('Loading Academy records…');return;}
 const views={overview:overview,courses:courses,cohorts:cohorts,learners:learners,timetable:timetable,fees:fees,reports:reports};content.innerHTML=(views[tab]||overview)();
 panel.querySelectorAll('#new-training-program-button,#new-cohort-button,#enrol-learner-button').forEach(b=>b.hidden=!canEdit());
}
function overview(){
 const ls=students(),cs=data.cohorts.filter(c=>!selected||c.id===selected),active=ls.filter(l=>!['Completed','Withdrawn'].includes(l.stage));
 const upcoming=data.sessions.filter(s=>(!selected||s.cohort_id===selected)&&!s.cancelled&&new Date(s.starts_at)>new Date()).sort((a,b)=>a.starts_at.localeCompare(b.starts_at)).slice(0,5);
 const attention=active.map(l=>({l,p:progress(l)})).filter(x=>x.p.reasons.length).slice(0,6);
 const stats=[['Active learners',active.length,'Currently enrolled'],['Running cohorts',cs.filter(c=>!['Completed','Cancelled'].includes(c.status)).length,'Planned and in delivery'],['Ready for review',active.filter(l=>progress(l).ready).length,'Completion requirements met'],['Completed',ls.filter(l=>l.stage==='Completed').length,'Recorded completions']];
 return `<div class="academy-stats">${stats.map(([a,b,c])=>`<article class="academy-stat"><span>${a}</span><strong>${b}</strong><small>${c}</small></article>`).join('')}</div><div class="academy-columns"><article class="surface"><h3>Next sessions</h3>${upcoming.length?upcoming.map(s=>`<div class="academy-row"><div><strong>${esc(s.title)}</strong><p class="academy-muted">${esc(cohort(s.cohort_id)?.name)} · ${time(s.starts_at)} CAT</p></div>${btn('cohort', 'Open cohort',s.cohort_id)}</div>`).join(''):empty('No upcoming sessions. Open a cohort to build its timetable.')}</article><article class="surface"><h3>Needs attention</h3>${attention.length?attention.map(({l,p})=>`<div class="academy-row"><div><strong>${esc(l.full_name)}</strong><p class="academy-muted">${esc(p.reasons[0])}</p></div>${btn('learner','Review',l.id)}</div>`).join(''):empty('No outstanding learner checks in this view.')}</article></div>`;
}
function courses(){return `<div class="academy-cards">${data.courses.filter(c=>`${c.name} ${c.category}`.toLowerCase().includes(query.toLowerCase())).map(c=>`<article class="academy-card">${tag(c.category)}<h3>${esc(c.name)}</h3><p>${esc(c.outcome)}</p><p class="academy-muted">${esc(c.duration)} · ${money(c.default_fee)}</p><p class="academy-muted">${c.minimum_attendance}% attendance · ${c.practical_minutes} practical minutes</p><p class="academy-muted">${esc((c.required_assessments||[]).join(' · ')||'No required assessments')}</p><footer>${action('course-edit','Edit course & criteria',c.id)}${tag(c.active?'Active':'Archived')}</footer></article>`).join('')||empty('Create your first course using Create course above.')}</div>`;}
function cohorts(){return `<div class="academy-cards">${data.cohorts.filter(c=>(!selected||selected===c.id)&&`${c.name} ${c.venue}`.toLowerCase().includes(query.toLowerCase())).map(c=>{const n=data.learners.filter(l=>l.cohort_id===c.id&&l.stage!=='Withdrawn').length;return `<article class="academy-card">${tag(c.status)}<h3>${esc(c.name)}</h3><p>${esc(course(c.course_id)?.name)}</p><p class="academy-muted">${esc(c.start_date)} – ${esc(c.end_date)}<br>${esc(c.venue)} · ${esc(staff(c.lead_instructor))}</p><div><strong>${n} / ${c.capacity} places</strong><div class="academy-progress"><span style="width:${Math.min(100,n/c.capacity*100)}%"></span></div></div><footer>${btn('cohort','Open cohort',c.id)}${action('cohort-edit','Edit',c.id)}</footer></article>`;}).join('')||empty('No matching cohorts.')}</div>`;}
function learners(){return table(['Learner','Cohort','Stage','Attendance','Next step'],students().map(l=>{const p=progress(l);return [`<button class="academy-link" data-academy="learner" data-id="${l.id}">${esc(l.full_name)}</button><p class="academy-muted">${esc(l.email||l.phone)}</p>`,esc(cohort(l.cohort_id)?.name),tag(l.stage),`${p.attendance}%`,esc(l.stage==='Completed'?'Completed':p.reasons[0]||'Ready for completion review')];}));}
function timetable(){return `<div class="academy-actions">${action('session-new','Schedule session',selected,true)}${btn('calendar','Open shared calendar')}</div>${table(['Session','Cohort','When (CAT)','Instructor','Actions'],data.sessions.filter(s=>(!selected||s.cohort_id===selected)&&`${s.title} ${cohort(s.cohort_id)?.name}`.toLowerCase().includes(query.toLowerCase())).sort((a,b)=>b.starts_at.localeCompare(a.starts_at)).map(s=>[`${esc(s.title)}<p>${tag(s.cancelled?'Cancelled':s.session_type)}</p>`,esc(cohort(s.cohort_id)?.name),`${time(s.starts_at)}<br><span class="academy-muted">to ${time(s.ends_at)}</span>`,esc(staff(s.instructor_id)),action('session-edit','Edit',s.id)+action('attendance','Register',s.id)]))}`;}
function invoice(l){return (state.invoices||[]).find(i=>i.id===l.invoice_id);}
function fees(){return `<p class="academy-muted">Invoices and payments remain in Finance. Link an invoice on the learner record; sponsored places retain sponsor details. A shared corporate invoice shows the full invoice balance, not a per-learner allocation.</p><div class="academy-actions">${btn('finance','Open Finance')}</div>${table(['Learner','Sponsor','Invoice','Invoice total','Received / balance','Status'],students().map(l=>{const i=invoice(l);return [`<button class="academy-link" data-academy="learner" data-id="${l.id}">${esc(l.full_name)}</button>`,esc(l.sponsor||'Self-funded'),esc(i?.number||(l.invoice_id?'Linked · Finance access required':'Not linked')),i?money(i.amount,i.currency):'—',i?`${money(data.payments.filter(p=>p.invoice_id===i.id).reduce((n,p)=>n+Number(p.amount),0),i.currency)} / ${money(Math.max(0,Number(i.amount)-data.payments.filter(p=>p.invoice_id===i.id).reduce((n,p)=>n+Number(p.amount),0)),i.currency)}`:'—',esc(i?.status||(l.fee_status==='Sponsored'?'Sponsored':'Link Finance invoice'))];}))}`;}
function reports(){const ls=students(),done=ls.filter(l=>l.stage==='Completed').length;return `<article class="surface"><h3>Training outcomes</h3><p>${ls.length} learner records · ${done} completed · ${ls.length?Math.round(done/ls.length*100):0}% completion</p><div class="academy-actions">${btn('export','Download learner report (CSV)')}</div><p class="academy-muted">Export respects your current cohort and search filters. Includes attendance, practical time, stage and completion gaps.</p></article><div style="margin-top:20px">${table(['Cohort','Enrolled','Completed','Withdrawn'],data.cohorts.filter(c=>!selected||c.id===selected).map(c=>{const a=ls.filter(l=>l.cohort_id===c.id);return [esc(c.name),a.length,a.filter(l=>l.stage==='Completed').length,a.filter(l=>l.stage==='Withdrawn').length];}))}</div>`;}
function modal(title,html){let d=$('academy-dialog');if(!d){d=document.createElement('dialog');d.id='academy-dialog';d.className='app-dialog academy-dialog';document.body.append(d);}d.innerHTML=`<div class="dialog-heading"><h2>${esc(title)}</h2><button type="button" class="icon-button" data-academy="close" aria-label="Close">×</button></div>${html}<p id="academy-form-error" class="form-error" role="alert"></p>`;if(!d.open)d.showModal();return d;}
const field=(name,label,value='',type='text',extra='')=>`<label class="field"><span>${esc(label)}</span><input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const area=(name,label,value='')=>`<label class="field field-wide"><span>${esc(label)}</span><textarea name="${name}" rows="3">${esc(value)}</textarea></label>`;
const select=(name,label,opts,value='',required=false)=>`<label class="field"><span>${esc(label)}</span><select name="${name}" ${required?'required':''}>${opts.map(o=>{const [k,v]=Array.isArray(o)?o:[o,o];return `<option value="${esc(k)}" ${String(value)===String(k)?'selected':''}>${esc(v)}</option>`;}).join('')}</select></label>`;
const check=(name,label,value)=>`<label class="check-field field-wide"><input type="checkbox" name="${name}" ${value?'checked':''}><span>${esc(label)}</span></label>`;
const staffOptions=()=>[['','Unassigned'],...data.staff.map(s=>[s.id,s.full_name])];
function edit(kind,id=''){
 let r={},body='',title='',submit='Save changes';
 if(kind==='course-edit'){r=course(id);title='Course & completion criteria';body=field('name','Course name',r.name,'text','required')+select('category','Category',['RPL','RPL Refresher','STEM','Technical','Corporate','Other'],r.category)+field('duration','Duration',r.duration,'text','required')+field('default_fee','Default fee (MWK)',r.default_fee,'number','min="0" step="0.01" required')+field('certificate_type','Certificate description',r.certificate_type,'text','required')+field('minimum_attendance','Minimum attendance (%)',r.minimum_attendance,'number','min="0" max="100" required')+field('practical_minutes','Signed practical minutes required',r.practical_minutes,'number','min="0" required')+area('required_assessments','Required assessments — one exact assessment title per line',(r.required_assessments||[]).join('\n'))+area('modules','Modules — one per line',r.modules)+area('requirements','Required documents / prerequisites',r.requirements)+area('outcome','Learning outcome',r.outcome)+check('active','Available for new cohorts',r.active);}
 if(kind==='cohort-edit'){r=cohort(id);title='Cohort settings';body=field('name','Cohort name',r.name,'text','required')+select('status','Status',['Planned','Open','Active','Assessment','Completed','Cancelled'],r.status)+select('lead_instructor','Lead instructor',staffOptions(),r.lead_instructor)+field('start_date','Start date',r.start_date,'date','required')+field('end_date','End date',r.end_date,'date','required')+field('venue','Venue',r.venue,'text','required')+field('capacity','Capacity',r.capacity,'number','min="1" required')+field('source_reference','Client / accepted request',r.source_reference)+select('project_id','Linked delivery project',[['','Not linked'],...(state.projects||[]).map(p=>[p.id,p.name])],r.project_id);}
 if(kind==='learner-edit'){r=learner(id);title='Learner record';body=field('full_name','Full name',r.full_name,'text','required')+field('email','Email',r.email,'email')+field('phone','Phone',r.phone,'text','required')+field('date_of_birth','Date of birth',r.date_of_birth,'date')+field('sponsor','Organisation / sponsor',r.sponsor)+select('invoice_id','Finance invoice',[['','Not linked'],...(state.invoices||[]).map(i=>[i.id,`${i.number} · ${i.client}`]),...(r.invoice_id&&!invoice(r)?[[r.invoice_id,'Existing link · Finance access required']]:[])],r.invoice_id)+field('guardian_name','Guardian name',r.guardian_name)+field('guardian_phone','Guardian contact number',r.guardian_phone)+area('collection_contacts','Authorised collection contacts',r.collection_contacts)+check('guardian_consent','Guardian consent received and checked',r.guardian_consent)+check('documents_complete','Required documents received and checked',r.documents_complete)+select('external_licence_status','External licence status',['Not recorded','Application pending','Submitted','Issued','Expired'],r.external_licence_status)+field('rpl_number','External RPL number',r.rpl_number)+field('rpl_expiry','External licence expiry',r.rpl_expiry,'date')+field('renewal_due','Follow-up due',r.renewal_due,'date')+area('skills','Skills / portfolio notes',r.skills)+check('alumni_consent','Consent received for alumni opportunities follow-up',r.alumni_consent)+area('notes','Learner notes',r.notes);}
 if(kind==='session-new'||kind==='session-edit'){r=kind==='session-edit'?data.sessions.find(s=>s.id===id):{cohort_id:id||selected,session_type:'Class'};title=kind==='session-edit'?'Edit session':'Schedule session';body=select('cohort_id','Cohort',data.cohorts.map(c=>[c.id,c.name]),r.cohort_id,true)+field('title','Session title',r.title,'text','required')+select('session_type','Type',['Class','Practical','Assessment','Field exercise','Other'],r.session_type)+select('instructor_id','Instructor',staffOptions(),r.instructor_id||cohort(r.cohort_id)?.lead_instructor)+field('starts_at','Starts (Malawi time)',localTime(r.starts_at),'datetime-local','required')+field('ends_at','Ends (Malawi time)',localTime(r.ends_at),'datetime-local','required')+field('venue','Venue',r.venue||cohort(r.cohort_id)?.venue)+check('cancelled','Cancel this session (keep historical attendance)',r.cancelled);}
 if(kind==='practical'){r=learner(id);title=`Practical log · ${r.full_name}`;submit='Save practical log';body=field('performed_on','Training date',day(),'date','required')+field('aircraft','Aircraft / equipment','','text','required')+field('exercise','Exercise / competency','','text','required')+field('minutes','Duration (minutes)','','number','required min="1" max="1440"')+area('notes','Instructor feedback')+check('signed','I confirm the learner completed this exercise',false);}
 if(kind==='document'){title='Add learner document';submit='Upload document';body=field('title','Document description','','text','required')+field('file','PDF or image','','file','required accept="application/pdf,image/*"');}
 if(kind==='material'){title='Add cohort learning resource';body=field('title','Resource title','','text','required')+field('resource_url','Resource link (HTTPS)','','url','required pattern="https://.*"')+area('description','Instructions / module');}
 if(kind==='assessment'){const l=learner(id),c=courseFor(l);title=`Assessment · ${l.full_name}`;submit='Record assessment';body=field('assessment_type','Assessment title',(c.required_assessments||[])[0]||'Final assessment','text','required list="academy-assessment-names"')+`<datalist id="academy-assessment-names">${(c.required_assessments||[]).map(a=>`<option value="${esc(a)}">`).join('')}</datalist>`+select('result','Result',['Pending','Pass','Fail','Competent','Not yet competent'],'Pending')+field('score','Score (%) — optional','','number','min="0" max="100" step="0.01"')+area('notes','Feedback / resit requirements')+field('file','Evidence — optional','','file','accept="application/pdf,image/*"');}
 if(kind==='attendance'){const s=data.sessions.find(s=>s.id===id);title=`Attendance · ${s.title}`;body=`<p class="field-wide academy-muted">${time(s.starts_at)} CAT. Unmarked elapsed sessions count as absence for completion.</p>`+data.learners.filter(l=>l.cohort_id===s.cohort_id&&l.stage!=='Withdrawn').map(l=>select(l.id,l.full_name,[['','Not recorded'],'Present','Absent','Late','Excused'],data.attendance.find(a=>a.session_id===id&&a.learner_id===l.id)?.status)).join('');submit='Save register';}
 if(kind==='stage'){r=learner(id);title='Update enrolment stage';body=select('stage','Stage',['Enquiry','Registered','Documents pending','Training','Assessment','Certification','Withdrawn'],r.stage);}
 modal(title,`<form id="academy-form" data-kind="${kind}" data-record="${esc(id)}"><div class="form-grid">${body}</div><div class="dialog-actions">${btn('close','Cancel')}<button class="primary-button" type="submit">${submit}</button></div></form>`);
}
async function viewLearner(id){
 const l=learner(id);if(!l)return;const p=progress(l),c=courseFor(l),certs=data.certificates.filter(x=>x.learner_id===id);
 modal(l.full_name,`<div class="academy-profile-head"><div><p>${esc(cohort(l.cohort_id)?.name)} · ${esc(c?.name)}</p><p class="academy-muted">${esc(l.email||'No email')} · ${esc(l.phone)}</p></div>${tag(l.stage)}</div><div class="academy-profile-grid"><div>Attendance<strong>${p.attendance}%</strong><small>${p.sessions} elapsed sessions</small></div><div>Signed practical time<strong>${p.mins} minutes</strong></div><div>Completion<strong>${p.ready?'Ready for review':`${p.reasons.length} checks pending`}</strong></div></div><div class="academy-actions">${action('learner-edit','Edit record',id)}${action('stage','Update stage',id)}${action('document','Add document',id)}${action('practical','Log practical',id)}${action('assessment','Record assessment',id)}</div><h3>Completion review</h3>${p.reasons.length?`<ul class="academy-checks">${p.reasons.map(r=>`<li>${esc(r)}</li>`).join('')}</ul>`:'<p>Local checks are met. Server validation runs when completion is approved.</p>'}${canApprove()&&!certs.some(c=>['CAGE course completion','CAGE attendance'].includes(c.certificate_type))?btn('issue','Approve CAGE completion',id,true):''}${certs.map(c=>`<p>${esc(c.certificate_number)} · ${esc(c.issued_on)} ${btn('certificate','View certificate',c.id)}</p>`).join('')}<details><summary>Documents (${data.documents.filter(d=>d.learner_id===id).length})</summary>${data.documents.filter(d=>d.learner_id===id).map(d=>`<p>${btn('file',d.title,d.file_path)}</p>`).join('')||'<p>No documents uploaded.</p>'}</details><details><summary>Assessment & resit history</summary>${table(['Assessment','Result','Date','Feedback'],data.assessments.filter(a=>a.learner_id===id).sort((a,b)=>b.assessed_at.localeCompare(a.assessed_at)).map(a=>[esc(a.assessment_type),esc(a.result)+(a.score!=null?` · ${a.score}%`:''),time(a.assessed_at),`${esc(a.notes||'')}${a.evidence_path?btn('file','Evidence',a.evidence_path):''}`]))}</details><details><summary>Practical history</summary>${table(['Date','Exercise','Minutes','Sign-off'],data.practical.filter(p=>p.learner_id===id).map(p=>[esc(p.performed_on),`${esc(p.exercise)}<br>${esc(p.aircraft)}`,p.minutes,esc(p.signed_off_by?staff(p.signed_off_by):'Not signed')]))}</details><details><summary>Guardian, licence & follow-up</summary><p>${esc(l.guardian_name||'No guardian')} · ${esc(l.guardian_phone||'')} · Consent: ${l.guardian_consent?'checked':'not recorded'}</p><p>Collection contacts: ${esc(l.collection_contacts||'Not recorded')}</p><p>External licence: ${esc(l.external_licence_status)} · ${esc(l.rpl_number||'')} · Expiry ${esc(l.rpl_expiry||'not recorded')}</p><p>Follow-up: ${esc(l.renewal_due||'Not scheduled')} · Alumni consent: ${l.alumni_consent?'Yes':'No'}</p><p class="academy-notes">${esc(l.notes||'')}</p></details>`);
}
function viewCohort(id){const c=cohort(id),ls=data.learners.filter(l=>l.cohort_id===id),ss=data.sessions.filter(s=>s.cohort_id===id);modal(c.name,`<p>${esc(course(c.course_id)?.name)} · ${esc(c.venue)} · ${esc(staff(c.lead_instructor))}</p><div class="academy-actions">${action('cohort-edit','Settings',id)}${action('session-new','Schedule session',id)}${action('material','Add learning resource',id)}${action('message','Cohort communication',id)}${action('equipment','Reserve equipment',id)}${c.project_id?btn('project','Delivery project',c.project_id):''}</div><h3>Timetable</h3>${table(['Session','When (CAT)','Register'],ss.sort((a,b)=>a.starts_at.localeCompare(b.starts_at)).map(s=>[esc(s.title)+(s.cancelled?' · Cancelled':''),time(s.starts_at),action('attendance','Attendance',s.id)]))}<h3 style="margin-top:24px">Learners</h3>${table(['Name','Stage','Attendance'],ls.map(l=>[`<button class="academy-link" data-academy="learner" data-id="${l.id}">${esc(l.full_name)}</button>`,esc(l.stage),`${progress(l).attendance}%`]))}<h3 style="margin-top:24px">Learning resources</h3>${data.materials.filter(m=>m.cohort_id===id).map(m=>`<div class="academy-row"><div><a href="${esc(/^https:\/\//.test(m.resource_url)?m.resource_url:'#')}" target="_blank" rel="noopener noreferrer">${esc(m.title)}</a><p>${esc(m.description||'')}</p></div></div>`).join('')||'<p>No resources added yet.</p>'}`);}
async function submit(form){
 const kind=form.dataset.kind,id=form.dataset.record,v=Object.fromEntries(new FormData(form));
 if(!canEdit())throw new Error('Training edit access required.');
 const nullable=names=>names.forEach(k=>v[k]=v[k]||null);
 if(kind==='course-edit'){for(const k of ['default_fee','minimum_attendance','practical_minutes'])v[k]=Number(v[k]);v.required_assessments=[...new Set(v.required_assessments.split('\n').map(x=>x.trim()).filter(Boolean))];v.active=!!v.active;await api().academySave('training_courses',v,id);}
 if(kind==='cohort-edit'){if(v.end_date<v.start_date)throw new Error('End date must follow the start date.');v.capacity=Number(v.capacity);nullable(['lead_instructor','project_id']);await api().academySave('training_cohorts',v,id);}
 if(kind==='learner-edit'){for(const k of ['guardian_consent','documents_complete','alumni_consent'])v[k]=!!v[k];nullable(['email','date_of_birth','invoice_id','rpl_expiry','renewal_due']);await api().academySave('learners',v,id);}
 if(kind==='session-new'||kind==='session-edit'){if(v.ends_at<=v.starts_at)throw new Error('Session end must be after its start.');v.starts_at=new Date(v.starts_at+':00+02:00').toISOString();v.ends_at=new Date(v.ends_at+':00+02:00').toISOString();v.cancelled=!!v.cancelled;nullable(['instructor_id']);await api().academySave('training_sessions',v,kind==='session-edit'?id:null);}
 if(kind==='practical'){await api().academySave('training_practical_logs',{...v,learner_id:id,minutes:Number(v.minutes),signed_off_by:v.signed?api().currentProfile().id:null});}
 if(kind==='document'){const f=form.elements.file.files[0];if(!f)throw new Error('Choose a document.');const uploaded=await api().uploadFile(f,'training',id);await api().academySave('training_documents',{learner_id:id,title:v.title,file_path:uploaded.path});}
 if(kind==='material'){if(!/^https:\/\//.test(v.resource_url))throw new Error('Use an HTTPS resource link.');await api().academySave('training_materials',{...v,cohort_id:id});}
 if(kind==='assessment'){const f=form.elements.file.files[0],uploaded=f?await api().uploadFile(f,'training',id):null;await api().opsSave('training_assessments',{learner_id:id,assessment_type:v.assessment_type.trim(),result:v.result,score:v.score===''?null:Number(v.score),assessor_id:api().currentProfile().id,notes:v.notes,evidence_path:uploaded?.path||null});}
 if(kind==='attendance'){const rows=Object.entries(v).filter(([,status])=>status).map(([learner_id,status])=>({session_id:id,learner_id,status}));if(!rows.length)throw new Error('Mark at least one learner.');await api().academyAttendance(rows);}
 if(kind==='stage')await api().updateLearnerStage(id,v.stage);
 $('academy-dialog').close();await load();showToast('Training record saved.');
}
async function certificate(id){
 const c=data.certificates.find(c=>c.id===id),l=learner(c.learner_id),co=cohort(l.cohort_id),cr=course(co.course_id);
 if(!['CAGE course completion','CAGE attendance'].includes(c.certificate_type)){modal('Historical certificate record',`<p>${esc(c.certificate_type)} · ${esc(c.certificate_number)} · ${esc(c.issued_on)}</p><p>Refer to the original issuer document.</p>${c.file_path?btn('file','Open original document',c.file_path):''}`);return;}
 modal('CAGE course completion',`<article class="surface"><p class="section-kicker">CAGE Training Academy</p><h3>${esc(c.certificate_type)}</h3><p>This records that <strong>${esc(l.full_name)}</strong> completed <strong>${esc(cr.name)}</strong>.</p><p>${esc(co.name)} · ${esc(co.start_date)} – ${esc(co.end_date)}</p><p>Issued ${esc(c.issued_on)}<br>Reference: ${esc(c.certificate_number)}</p><p class="academy-muted">A CAGE course completion record. It does not replace an externally issued aviation licence.</p>${['CAGE course completion','CAGE attendance'].includes(c.certificate_type)?btn('certificate-pdf','Download certificate PDF',id,true):'<p>Historical certificate record. Refer to the original issuer document.</p>'}</article>`);
}
async function certificatePDF(id){
 const c=data.certificates.find(c=>c.id===id),l=learner(c.learner_id),co=cohort(l.cohort_id),cr=course(co.course_id);
 if(!['CAGE course completion','CAGE attendance'].includes(c.certificate_type))throw new Error('This is an external or legacy certificate record.');
 if(!window.PDFLib)throw new Error('PDF component is still loading. Please retry.');
 const {PDFDocument,StandardFonts,rgb}=PDFLib,doc=await PDFDocument.create(),p=doc.addPage([842,595]),font=await doc.embedFont(StandardFonts.Helvetica),bold=await doc.embedFont(StandardFonts.HelveticaBold);
 const safe=v=>String(v).replace(/[^\x20-\x7E]/g,'?');
 function text(v,y,size=16,b=false){const f=b?bold:font,s=safe(v);const w=f.widthOfTextAtSize(s,size);p.drawText(s,{x:(842-w)/2,y,size,font:f,color:rgb(.12,.2,.28)});}
 p.drawRectangle({x:26,y:26,width:790,height:543,borderWidth:2,borderColor:rgb(0,.68,.94)});
 text('CAGE TRAINING ACADEMY',505,20,true);text('COURSE COMPLETION',449,30,true);text('This certifies that',399);text(l.full_name,355,Math.min(27,680/Math.max(1,bold.widthOfTextAtSize(safe(l.full_name),1))),true);text('has completed',314);text(cr.name,270,Math.min(21,680/Math.max(1,bold.widthOfTextAtSize(safe(cr.name),1))),true);text(`${co.start_date} to ${co.end_date}`,230,14);text(`Issued: ${c.issued_on}`,173,14);text(c.certificate_number,130,10);text('CAGE course completion does not confer an external aviation licence.',85,11);
 download(await doc.save(),'application/pdf',`CAGE_Certificate_${c.certificate_number}.pdf`);
}
function download(bytes,type,name){const url=URL.createObjectURL(new Blob([bytes],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function exportReport(){const cell=v=>{let s=String(v??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';};const rows=[['Learner','Cohort','Stage','Attendance %','Signed minutes','Next steps','Sponsor','Alumni consent'],...students().map(l=>{const p=progress(l);return [l.full_name,cohort(l.cohort_id)?.name,l.stage,p.attendance,p.mins,p.reasons.join('; '),l.sponsor,l.alumni_consent?'Yes':'No'];})];download('\uFEFF'+rows.map(r=>r.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8',`CAGE_Academy_${day()}.csv`);}
async function handle(action,id){
 if(action==='tab'){tab=id;remember();render();return;}
 if(action==='refresh')return load();
 if(action==='close')return $('academy-dialog')?.close();
 if(action==='learner')return viewLearner(id);
 if(action==='cohort')return viewCohort(id);
 if(['course-edit','cohort-edit','learner-edit','session-new','session-edit','practical','document','material','assessment','attendance','stage'].includes(action)){if(!canEdit())throw new Error('Training edit access required.');return edit(action,id);}
 if(action==='file')return api().openFile(id);
 if(action==='certificate')return certificate(id);
 if(action==='certificate-pdf')return certificatePDF(id);
 if(action==='export')return exportReport();
 if(action==='issue'){const p=await api().academyCompletion(id);if(!p.ready)throw new Error(p.reasons.join('\n'));modal('Approve completion',`<p>All recorded course requirements are met for <strong>${esc(learner(id).full_name)}</strong>. Approving will create a numbered CAGE completion certificate and mark this learner completed.</p><div class="academy-actions">${btn('issue-confirm','Approve and issue certificate',id,true)}${btn('close','Cancel')}</div>`);return;}
 if(action==='issue-confirm'){if(!canApprove())throw new Error('Manager approval required.');const c=await api().academyCompletion(id,true);await load();return certificate(c.id);}
 if(action==='message'){$('academy-dialog').close();return window.CAGE_OPS.openCohort(id,'message',data);}
 if(action==='equipment'){const c=cohort(id);if(!c.project_id)throw new Error('Link a delivery project in Cohort settings first. Equipment reservations belong to that project.');$('academy-dialog').close();return window.CAGE_OPS.reserveForTraining(c.project_id,c.name);}
 if(['calendar','finance','project'].includes(action)){$('academy-dialog')?.close();setView(action==='project'?'projects':action);if(action==='project')openProject(id);}
}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-academy]');if(!b)return;b.disabled=true;try{await handle(b.dataset.academy,b.dataset.id);}catch(err){const target=$('academy-dialog')?.open?$('academy-form-error'):null;if(target)target.textContent=err.message;else showToast(err.message);}finally{b.disabled=false;}});
document.addEventListener('submit',async e=>{if(e.target.id!=='academy-form')return;e.preventDefault();if(e.target.dataset.submitting==='true')return;e.target.dataset.submitting='true';const b=e.submitter;if(b)b.disabled=true;$('academy-form-error').textContent='';try{await submit(e.target);}catch(err){$('academy-form-error').textContent=err.message;}finally{e.target.dataset.submitting='false';if(b)b.disabled=false;}});
root.addEventListener('input',e=>{if(e.target.id==='academy-query'){query=e.target.value;remember();const position=e.target.selectionStart;render();$('academy-query').focus();$('academy-query').setSelectionRange(position,position);}});
root.addEventListener('change',e=>{if(e.target.id==='academy-cohort-filter'){selected=e.target.value;remember();render();}});
window.addEventListener('cage:training-loaded',load);
window.addEventListener('cage:session-ready',()=>{try{const saved=JSON.parse(sessionStorage.getItem(key())||'{}');tab=saved.tab||'overview';selected=saved.selected||'';query=saved.query||'';}catch{}load();});
window.addEventListener('focus',()=>{if(activeView==='training'&&!$('academy-dialog')?.open)load();});
window.CAGE_ACADEMY={load,progress,async restore(saved){await load();if(!data)throw new Error(loadError||'Academy records unavailable');const f=saved.forms.find(f=>f.id==='academy-form');if(f)edit(f.data.kind,f.data.record);},calendarEvents(){return (data?.sessions||[]).filter(s=>!s.cancelled).map(s=>({id:'academy:'+s.id,date:localTime(s.starts_at).slice(0,10),start:localTime(s.starts_at).slice(11),end:localTime(s.ends_at).slice(11),type:'Training',title:s.title,owner:data.staff.find(p=>p.id===s.instructor_id)?.email?.split('@')[0]||'',project:cohort(s.cohort_id)?.project_id||''}));}};
render();
})();
